 38	/**
 39	 * Helper class to build {@link MetricsSource} object from annotations.
 40	 * <p>
 41	 * For a given source object:
 42	 * <ul>
 43	 * <li>Sets the {@link Field}s annotated with {@link Metric} to
 44	 * {@link MutableMetric} and adds it to the {@link MetricsRegistry}.</li>
 45	 * <li>
 46	 * For {@link Method}s annotated with {@link Metric} creates
 47	 * {@link MutableMetric} and adds it to the {@link MetricsRegistry}.</li>
 48	 * </ul>
 49	 */
 50	@InterfaceAudience.Private
 51	public class MetricsSourceBuilder {
 52	  private static final Logger LOG =
 53	      LoggerFactory.getLogger(MetricsSourceBuilder.class);
 54	
 55	  private final Object source;
 56	  private final MutableMetricsFactory factory;
 57	  private final MetricsRegistry registry;
 58	  private MetricsInfo info;
 59	  private boolean hasAtMetric = false;
 60	  private boolean hasRegistry = false;
 61	
 62	  MetricsSourceBuilder(Object source, MutableMetricsFactory factory) {
 63	    this.source = checkNotNull(source, "source");
 64	    this.factory = checkNotNull(factory, "mutable metrics factory");
 65	    Class<?> cls = source.getClass();
 66	    registry = initRegistry(source);
 67	
 68	    for (Field field : ReflectionUtils.getDeclaredFieldsIncludingInherited(cls)) {
 69	      add(source, field);
 70	    }
 71	    for (Method method : ReflectionUtils.getDeclaredMethodsIncludingInherited(cls)) {
 72	      add(source, method);
 73	    }
 74	  }
 75	
 76	  public MetricsSource build() {
 77	    if (source instanceof MetricsSource) {
 78	      if (hasAtMetric && !hasRegistry) {
 79	        throw new MetricsException("Hybrid metrics: registry required.");
 80	      }
 81	      return (MetricsSource) source;
 82	    }
 83	    else if (!hasAtMetric) {
 84	      throw new MetricsException("No valid @Metric annotation found.");
 85	    }
 86	    return new MetricsSource() {
 87	      @Override
 88	      public void getMetrics(MetricsCollector builder, boolean all) {
 89	        registry.snapshot(builder.addRecord(registry.info()), all);
 90	      }
 91	    };
 92	  }
 93	
 94	  public MetricsInfo info() {
 95	    return info;
 96	  }
 97	
 98	  private MetricsRegistry initRegistry(Object source) {
 99	    Class<?> cls = source.getClass();
100	    MetricsRegistry r = null;
101	    // Get the registry if it already exists.
102	    for (Field field : ReflectionUtils.getDeclaredFieldsIncludingInherited(cls)) {
103	      if (field.getType() != MetricsRegistry.class) continue;
104	      try {
105	        field.setAccessible(true);
106	        r = (MetricsRegistry) field.get(source);
107	        hasRegistry = r != null;
108	        break;
109	      } catch (Exception e) {
110	        LOG.warn("Error accessing field "+ field, e);
111	        continue;
112	      }
113	    }
114	    // Create a new registry according to annotation
115	    for (Annotation annotation : cls.getAnnotations()) {
116	      if (annotation instanceof Metrics) {
117	        Metrics ma = (Metrics) annotation;
118	        info = factory.getInfo(cls, ma);
119	        if (r == null) {
120	          r = new MetricsRegistry(info);
121	        }
122	        r.setContext(ma.context());
123	      }
124	    }
125	    if (r == null) return new MetricsRegistry(cls.getSimpleName());
126	    return r;
127	  }
128	
129	  /**
130	   * Change the declared field {@code field} in {@code source} Object to
131	   * {@link MutableMetric}
132	   */
133	  private void add(Object source, Field field) {
134	    for (Annotation annotation : field.getAnnotations()) {
135	      if (!(annotation instanceof Metric)) {
136	        continue;
137	      }
138	      try {
139	        // skip fields already set
140	        field.setAccessible(true);
141	        if (field.get(source) != null) continue;
142	      } catch (Exception e) {
143	        LOG.warn("Error accessing field "+ field +" annotated with"+
144	                 annotation, e);
145	        continue;
146	      }
147	      MutableMetric mutable = factory.newForField(field, (Metric) annotation,
148	                                                  registry);
149	      if (mutable != null) {
150	        try {
151	          field.set(source, mutable); // Set the source field to MutableMetric
152	          hasAtMetric = true;
153	        } catch (Exception e) {
154	          throw new MetricsException("Error setting field "+ field +
155	                                     " annotated with "+ annotation, e);
156	        }
157	      }
158	    }
159	  }
160	
161	  /** Add {@link MutableMetric} for a method annotated with {@link Metric} */
162	  private void add(Object source, Method method) {
163	    for (Annotation annotation : method.getAnnotations()) {
164	      if (!(annotation instanceof Metric)) {
165	        continue;
166	      }
167	      factory.newForMethod(source, method, (Metric) annotation, registry);
168	      hasAtMetric = true;
169	    }
170	  }
